// What the player did at a decision point (task 4.2, spec gameplay-loop "Waiting is a decision").
enum class DecisionKind : std::uint8_t {
  // No order placed, cancelled or moved, no leverage or margin change, and no exposure.
  Wait = 0,
  // No such command while a position (perpetual or option) stayed open.
  Hold = 1,
  // At least one accepted command that placed, cancelled or moved an order, or changed leverage or margin.
  Act = 2,
};

constexpr const char* json_name(DecisionKind v) {
  switch (v) {
    case DecisionKind::Wait: return "wait";
    case DecisionKind::Hold: return "hold";
    case DecisionKind::Act: return "act";
  }
  return "unknown";
}

// How a round trip ended (scoring v10: from the order type; a stop in profit is a stop).
enum class ExitReason : std::uint8_t {
  Stop = 0,
  Target = 1,
  Manual = 2,
  Liquidation = 3,
  Open = 4,
  Expiry = 5,
  MarginCall = 6,
  Trailing = 7,
};

constexpr const char* json_name(ExitReason v) {
  switch (v) {
    case ExitReason::Stop: return "stop";
    case ExitReason::Target: return "target";
    case ExitReason::Manual: return "manual";
    case ExitReason::Liquidation: return "liquidation";
    case ExitReason::Open: return "open";
    case ExitReason::Expiry: return "expiry";
    case ExitReason::MarginCall: return "margin_call";
    case ExitReason::Trailing: return "trailing";
  }
  return "unknown";
}

// A moment of the coach review (tl_coach_review, add-practice-and-advanced-strategies design D17): the
// first nine are warnings, the last four good moments.
enum class CoachMomentCode : std::uint8_t {
  // A perpetual position opened or grown at this bar with no protective stop working after the decision.
  EntryWithoutStop = 0,
  // A reduce-only stop moved away from the price.
  StopMovedAway = 1,
  // An add to a long while the close is below SMA(20) and below the lowest low of the previous 10 bars
  // (mirrored for a short).
  AddedAgainstStructure = 2,
  // An entry whose risk to its stop is above 2% of the run's initial capital.
  RiskAboveBudget = 3,
  // A position held over the next bar's announced release with no stop (or vega above the mission's limit).
  HeldIntoReleaseUnhedged = 4,
  // An entry within 3 bars of a losing close, without a plan or at 1.5x its size.
  RevengeTrade = 5,
  // An entry after 4+ closes its way, more than 2 ATR beyond SMA(20), with no stop or one more than 2 ATR away.
  FomoEntry = 6,
  // An add at a worse price while losing that lifts the risk above the first entry's plan, or has no stop.
  AveragingDown = 7,
  // A mission risk limit exceeded at this close (the first close of each breach).
  RiskLimitExceeded = 8,
  // A losing trade closed at or inside its plan's invalidation.
  CutAtInvalidation = 9,
  // The stop moved to the average entry or beyond once the open profit reached 1R.
  StopToBreakevenAfter1r = 10,
  // Part of the position closed at a profit of 1R or more, the rest kept.
  PartialAtTarget = 11,
  // Flat, with no entry working, before the next bar's announced release.
  StayedFlatBeforeRelease = 12,
};

constexpr const char* json_name(CoachMomentCode v) {
  switch (v) {
    case CoachMomentCode::EntryWithoutStop: return "entry_without_stop";
    case CoachMomentCode::StopMovedAway: return "stop_moved_away";
    case CoachMomentCode::AddedAgainstStructure: return "added_against_structure";
    case CoachMomentCode::RiskAboveBudget: return "risk_above_budget";
    case CoachMomentCode::HeldIntoReleaseUnhedged: return "held_into_release_unhedged";
    case CoachMomentCode::RevengeTrade: return "revenge_trade";
    case CoachMomentCode::FomoEntry: return "fomo_entry";
    case CoachMomentCode::AveragingDown: return "averaging_down";
    case CoachMomentCode::RiskLimitExceeded: return "risk_limit_exceeded";
    case CoachMomentCode::CutAtInvalidation: return "cut_at_invalidation";
    case CoachMomentCode::StopToBreakevenAfter1r: return "stop_to_breakeven_after_1r";
    case CoachMomentCode::PartialAtTarget: return "partial_at_target";
    case CoachMomentCode::StayedFlatBeforeRelease: return "stayed_flat_before_release";
  }
  return "unknown";
}

// A reference structure of the strategy comparison (scoring v13, add-academy-and-strategies design D8;
// m18-m22 since scoring v14).
enum class ComparisonStrategy : std::uint8_t {
  // m13: a call at the money.
  NakedCall = 0,
  // m13: that call bought, the next strike up written.
  BullCallSpread = 1,
  // m14, m15: the perpetual long alone, held to the end.
  LongOnly = 2,
  // m14: the long plus a call about 5% out of the money written, written again at each settlement.
  CoveredCall = 3,
  // m15: the long with a protective stop 2 x ATR(14) below the entry close.
  AtrStop = 4,
  // m15: the long plus a put at the money of the second expiry.
  AtmPut = 5,
  // m15: the long plus a put about 5% out of the money of the second expiry.
  OtmPut = 6,
  // m16: a put and a call 2 strikes out written, held to settlement.
  ShortStrangle = 7,
  // m16: the strangle plus the strikes 4 out bought (wings), held to settlement.
  IronCondor = 8,
  // m17: a put at the money written and held to settlement.
  HoldToSettlement = 9,
  // m17: the same put bought back 5 bars before its expiry.
  CloseBeforeExpiry = 10,
  // m17: the same put rolled 5 bars before each expiry into the next expiry's put at the money.
  RollBeforeExpiry = 11,
  // Scoring v14 (add-practice-and-advanced-strategies D13). m18: a straddle at the money of the first
  // expiry, held to its settlement.
  UnhedgedStraddle = 12,
  // m18: the same straddle, its delta brought to zero with the perpetual at every 4th close.
  HedgedEvery4 = 13,
  // m18: the same straddle, hedged whenever |delta| exceeds 40% of the contracts.
  HedgedBand = 14,
  // m19: the perpetual short alone at 5x, held to the end.
  UnhedgedShort = 15,
  // m19: the short plus a synthetic long (call bought, put written at the money of the last expiry), 5x.
  HedgedCarry5x = 16,
  // m19: the same hedged carry with the perpetual at 2x.
  HedgedCarry2x = 17,
  // m20: a straddle of the last expiry bought at the announcement and sold the bar before the release.
  EarlySellBefore = 18,
  // m20: the same straddle held through the release (sold 3 bars after it).
  EarlyHoldThrough = 19,
  // m20: a straddle of the first expiry bought the bar before the release, sold 3 bars after it.
  LateHoldThrough = 20,
  // m20: that straddle written the bar before the release, bought back 3 bars after it.
  ShortStraddleThrough = 21,
  // m21: a call calendar at the money (near written, next bought), closed at the near expiry.
  CalendarAtm = 22,
  // m21: a diagonal: the next expiry's call one strike up bought instead.
  DiagonalUp = 23,
  // m21: a straddle of the near expiry written and held to its settlement.
  ShortStraddleNear = 24,
  // m22: in 3 bars after the headline with its move, 1% at risk to a 2 x ATR stop, all out at 2R.
  AllOut2R = 25,
  // m22: half out at +1R, the stop to breakeven, the rest trailed at 2 x ATR.
  ManagedExit = 26,
  // m22: the initial stop only, held to the end.
  HoldInitialStop = 27,
};

constexpr const char* json_name(ComparisonStrategy v) {
  switch (v) {
    case ComparisonStrategy::NakedCall: return "naked_call";
    case ComparisonStrategy::BullCallSpread: return "bull_call_spread";
    case ComparisonStrategy::LongOnly: return "long_only";
    case ComparisonStrategy::CoveredCall: return "covered_call";
    case ComparisonStrategy::AtrStop: return "atr_stop";
    case ComparisonStrategy::AtmPut: return "atm_put";
    case ComparisonStrategy::OtmPut: return "otm_put";
    case ComparisonStrategy::ShortStrangle: return "short_strangle";
    case ComparisonStrategy::IronCondor: return "iron_condor";
    case ComparisonStrategy::HoldToSettlement: return "hold_to_settlement";
    case ComparisonStrategy::CloseBeforeExpiry: return "close_before_expiry";
    case ComparisonStrategy::RollBeforeExpiry: return "roll_before_expiry";
    case ComparisonStrategy::UnhedgedStraddle: return "unhedged_straddle";
    case ComparisonStrategy::HedgedEvery4: return "hedged_every_4";
    case ComparisonStrategy::HedgedBand: return "hedged_band";
    case ComparisonStrategy::UnhedgedShort: return "unhedged_short";
    case ComparisonStrategy::HedgedCarry5x: return "hedged_carry_5x";
    case ComparisonStrategy::HedgedCarry2x: return "hedged_carry_2x";
    case ComparisonStrategy::EarlySellBefore: return "early_sell_before";
    case ComparisonStrategy::EarlyHoldThrough: return "early_hold_through";
    case ComparisonStrategy::LateHoldThrough: return "late_hold_through";
    case ComparisonStrategy::ShortStraddleThrough: return "short_straddle_through";
    case ComparisonStrategy::CalendarAtm: return "calendar_atm";
    case ComparisonStrategy::DiagonalUp: return "diagonal_up";
    case ComparisonStrategy::ShortStraddleNear: return "short_straddle_near";
    case ComparisonStrategy::AllOut2R: return "all_out_2r";
    case ComparisonStrategy::ManagedExit: return "managed_exit";
    case ComparisonStrategy::HoldInitialStop: return "hold_initial_stop";
  }
  return "unknown";
}

// Advice in the debrief: a long or short read is right when the close 5 bars after the next open moved its way.
enum class AdviceOutcome : std::uint8_t {
  Right = 0,
  Wrong = 1,
  Wait = 2,
  Open = 3,
};

constexpr const char* json_name(AdviceOutcome v) {
  switch (v) {
    case AdviceOutcome::Right: return "right";
    case AdviceOutcome::Wrong: return "wrong";
    case AdviceOutcome::Wait: return "wait";
    case AdviceOutcome::Open: return "open";
  }
  return "unknown";
}

